"""Merge user data from three sources with differing formats/schemas."""
import json
import math
import pandas as pd

FIELDS = ["name", "email", "created_date", "status"]
PRIORITY = ["source_a", "source_b", "source_c"]


def norm_date(value):
    if value is None:
        return None
    if isinstance(value, float) and math.isnan(value):
        return None
    s = str(value).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    ts = pd.to_datetime(s, errors="coerce")
    if pd.isna(ts):
        return s
    return ts.strftime("%Y-%m-%d")


def norm_status(value):
    if value is None:
        return None
    if isinstance(value, float) and math.isnan(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    s = str(value).strip().lower()
    if s in ("", "nan", "none", "null"):
        return None
    if s in ("true", "1", "yes", "t", "y"):
        return "active"
    if s in ("false", "0", "no", "f", "n"):
        return "inactive"
    return s


def norm_id(value):
    if value is None:
        return None
    if isinstance(value, float) and math.isnan(value):
        return None
    s = str(value).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    try:
        f = float(s)
        if f == int(f):
            return int(f)
    except (TypeError, ValueError):
        return s
    return s


def norm_str(value):
    if value is None:
        return None
    if isinstance(value, float) and math.isnan(value):
        return None
    s = str(value).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    return s


def load_source_a(path):
    with open(path) as fh:
        rows = json.load(fh)
    out = []
    for r in rows:
        out.append({
            "user_id": norm_id(r.get("id", r.get("user_id"))),
            "name": norm_str(r.get("full_name", r.get("name"))),
            "email": norm_str(r.get("email")),
            "created_date": norm_date(r.get("registration_date")),
            "status": norm_status(r.get("status")),
        })
    return out


def load_source_b(path):
    df = pd.read_csv(path, dtype=str, keep_default_na=False)
    out = []
    for _, r in df.iterrows():
        status = r.get("is_active", None)
        status = None if status in ("", None) else str(status)
        out.append({
            "user_id": norm_id(r.get("user_id")),
            "name": norm_str(r.get("name")),
            "email": norm_str(r.get("email_address")),
            "created_date": norm_date(r.get("created_at")),
            "status": norm_status(status),
        })
    return out


def load_source_c(path):
    df = pd.read_parquet(path)
    out = []
    for _, r in df.iterrows():
        rid = r.get("userId", r.get("user_id"))
        if isinstance(rid, float) and not math.isnan(rid):
            rid = int(rid)
        out.append({
            "user_id": norm_id(rid),
            "name": norm_str(r.get("userName", r.get("name"))),
            "email": norm_str(r.get("email")),
            "created_date": norm_date(r.get("joined", r.get("created_date"))),
            "status": norm_status(r.get("active", r.get("status"))),
        })
    return out


def main():
    loaders = {
        "source_a": load_source_a("/data/source_a/users.json"),
        "source_b": load_source_b("/data/source_b/users.csv"),
        "source_c": load_source_c("/data/source_c/users.parquet"),
    }

    # per-source record index by user id (last row wins within a source)
    per_source = {}
    order = []
    for src in PRIORITY:
        idx = {}
        for rec in loaders[src]:
            uid = rec["user_id"]
            if uid is None:
                continue
            idx[uid] = rec
        per_source[src] = idx
        for uid in idx:
            if uid not in order:
                order.append(uid)

    merged = []
    conflicts = []
    for uid in sorted(order, key=lambda x: (isinstance(x, str), x)):
        row = {"user_id": uid}
        for field in FIELDS:
            present = {}
            for src in PRIORITY:
                rec = per_source[src].get(uid)
                if rec is not None and rec.get(field) is not None:
                    present[src] = rec[field]
            if not present:
                row[field] = None
                continue
            selected = present[PRIORITY[0]] if PRIORITY[0] in present else None
            if selected is None:
                for src in PRIORITY:
                    if src in present:
                        selected = present[src]
                        break
            row[field] = selected
            distinct = {str(v) for v in present.values()}
            if len(distinct) > 1:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": {src: present[src] for src in PRIORITY},
                    "selected": selected,
                })
        merged.append(row)

    out_df = pd.DataFrame(merged, columns=["user_id", "name", "email", "created_date", "status"])
    out_df["user_id"] = out_df["user_id"].astype("int64")
    for col in ["name", "email", "created_date", "status"]:
        out_df[col] = out_df[col].astype("object")
    out_df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as fh:
        json.dump(report, fh, indent=2)

    print(out_df.to_string())
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
